@import url('https://fonts.googleapis.com/css2?family=Barlow+Condensed:wght@400;500;600;700;800;900&family=IBM+Plex+Mono:wght@400;500;600;700&display=swap');
:root{--ink:#07121b;--panel:rgba(6,17,25,.78);--line:rgba(150,198,211,.25);--muted:#77909c;--white:#e6f0ef;--cyan:#8ed5d5;--amber:#f4ae57;--red:#f35e53}*{box-sizing:border-box}html,body{margin:0;width:100%;height:100%;overflow:hidden;background:#08151d;color:var(--white);font-family:'IBM Plex Mono',monospace}button{font:inherit}.game-shell{position:relative;width:100vw;height:100dvh;overflow:hidden;background:#11202a;isolation:isolate}#game{position:absolute;inset:0;width:100%;height:100%;z-index:-1}.vignette{position:absolute;inset:0;pointer-events:none;background:radial-gradient(ellipse at 50% 48%,transparent 25%,rgba(1,8,13,.22) 70%,rgba(1,7,11,.76) 130%),linear-gradient(180deg,rgba(4,13,19,.68),transparent 25%,transparent 70%,rgba(3,10,15,.55)}.topbar{position:absolute;z-index:2;top:0;left:0;width:100%;height:58px;padding:0 31px;display:flex;align-items:center;justify-content:space-between;border-bottom:1px solid rgba(202,226,228,.12);background:linear-gradient(180deg,rgba(4,13,19,.68),rgba(4,13,19,.22));font-size:10px;letter-spacing:1.55px;color:#c3d1d1}.brand{display:flex;align-items:center;gap:12px;font-weight:600}.brand i{font-style:normal;color:#4e737d;padding:0 4px}.brand-mark{display:grid;place-items:center;width:27px;height:27px;border:1px solid var(--cyan);color:var(--cyan);font-size:10px;font-weight:700;letter-spacing:-.7px}.top-right{display:flex;align-items:center;gap:10px;color:#8da2a9;font-size:9px}.live-dot{width:6px;height:6px;background:#80d2ba;box-shadow:0 0 10px #80d2ba;border-radius:50%}.sep{color:#425963}.mission-strip{position:absolute;z-index:2;top:76px;left:50%;transform:translateX(-50%);width:min(440px,40vw);height:44px;border:1px solid rgba(175,213,218,.26);background:rgba(5,15,22,.58);display:flex;align-items:center;justify-content:space-between;padding:0 13px;clip-path:polygon(0 0,97% 0,100% 25%,100% 100%,3% 100%,0 75%)}.mission-label{font-size:8px;letter-spacing:.8px;color:#9eb2b4}.mission-label b{color:#e6efec;font-size:10px}.mission-label span{color:#496771}.mission-objective{display:flex;align-items:center;gap:6px;font-size:8px;font-weight:600;letter-spacing:.45px;color:#d9e8e4}.target-icon{font-size:14px;color:var(--amber)}.mission-progress{display:flex;gap:6px;align-items:center;font-size:9px;color:#829ba1}.mission-progress b{color:var(--cyan)}.progress-track{height:3px;width:42px;background:#30434a}.progress-track i{display:block;width:0;height:100%;background:var(--cyan);transition:width .25s}.hud-left{position:absolute;top:23%;left:29px;width:164px;display:grid;gap:9px}.hud-card{padding:10px 12px 9px;background:linear-gradient(110deg,rgba(6,17,24,.75),rgba(8,21,28,.32));border-left:2px solid rgba(141,196,202,.55);border-top:1px solid rgba(164,205,209,.16);clip-path:polygon(0 0,93% 0,100% 20%,100% 100%,0 100%)}.hud-caption{font-size:8px;letter-spacing:1.4px;color:#8ba3aa}.hud-card>div:nth-child(2){margin-top:4px;display:flex;align-items:baseline;gap:5px}.hud-card strong{font:600 25px 'Barlow Condensed',sans-serif;letter-spacing:.5px;color:#e5efeb}.hud-card small{font-size:8px;color:#92aab0}.meter{height:2px;background:#3a5158;margin-top:8px}.meter i{height:100%;width:67%;display:block;background:var(--cyan)}.speed-card strong{font-size:29px;color:#b1dddd}.speed-status{margin-top:0;font-size:8px;letter-spacing:1px;color:#8ca8ad}.speed-status span{color:#7ed4b3;margin-left:4px;font-size:7px}.threat-card{display:flex;justify-content:space-between;align-items:center;padding-top:9px;padding-bottom:9px}.threat-readout{gap:7px!important;margin:0!important}.threat-readout strong{font:600 11px 'IBM Plex Mono';letter-spacing:1px;color:#8ad6b7}.threat-dot{width:6px;height:6px;border-radius:100%;background:#79d4a9;box-shadow:0 0 8px #79d4a9}.hud-right{position:absolute;top:22%;right:29px;width:185px;display:grid;gap:11px}.radar-panel,.weapon-panel{background:rgba(5,16,23,.66);border:1px solid rgba(156,199,206,.23);padding:9px 10px}.radar-head,.radar-foot{display:flex;justify-content:space-between;font-size:7px;letter-spacing:.7px;color:#91a9ad}.radar-head span:last-child{color:#657f86}.radar{position:relative;width:118px;height:118px;border-radius:50%;margin:12px auto 8px;border:1px solid rgba(110,192,185,.49);background:repeating-radial-gradient(circle,transparent 0 17px,rgba(110,192,185,.13) 18px 19px),linear-gradient(90deg,transparent 49.5%,rgba(110,192,185,.2) 50%,transparent 50.5%),linear-gradient(0deg,transparent 49.5%,rgba(110,192,185,.2) 50%,transparent 50.5%),rgba(29,67,66,.15);overflow:hidden}.radar:before,.radar:after{content:'';position:absolute;inset:50% auto auto 50%;width:50%;height:50%;transform-origin:top left;background:linear-gradient(38deg,rgba(107,220,180,.34),transparent 72%);animation:sweep 5s linear infinite}.radar:after{transform:rotate(90deg);opacity:.2}.radar-sweep{position:absolute;inset:0;border-radius:50%;background:conic-gradient(from 330deg,transparent 0deg,rgba(101,214,178,.34) 18deg,transparent 55deg);animation:sweep 5s linear infinite}.radar-blip{position:absolute;width:4px;height:4px;background:#f06859;border-radius:50%;box-shadow:0 0 7px #fa6357}.b1{left:69%;top:30%}.b2{left:31%;top:67%}.b3{left:78%;top:76%;opacity:.6}.radar-player{position:absolute;left:47%;top:45%;font-size:10px;color:#b1e6d3}.radar-cross{position:absolute;background:rgba(133,195,186,.14)}.radar-cross.x{width:100%;height:1px;left:0;top:50%}.radar-cross.y{height:100%;width:1px;left:50%;top:0}.radar-foot{font-size:6px;color:#849ba0}.radar-foot span:first-child{color:#e8796c}.weapon-panel{padding:10px 10px 3px}.weapon-panel>.hud-caption{display:block;margin:0 0 6px}.weapon-row{height:41px;border-top:1px solid rgba(140,179,187,.12);display:flex;align-items:center;gap:8px}.weapon-glyph{width:21px;text-align:center;color:#8fced0;font-size:18px}.weapon-name{display:grid;gap:2px;flex:1}.weapon-name b{font-size:9px;letter-spacing:.7px}.weapon-name small{font-size:6px;color:#8299a0}.weapon-ready{font-size:6px;color:#83d2aa;letter-spacing:.6px}.missile-row .weapon-glyph{color:var(--amber)}.reticle{position:absolute;left:50%;top:53%;width:124px;height:112px;transform:translate(-50%,-50%);opacity:.86;pointer-events:none;transition:transform .12s}.reticle-circle{position:absolute;left:20px;top:7px;width:84px;height:84px;border:1px solid rgba(183,225,222,.46);border-radius:50%}.reticle-center{position:absolute;left:59px;top:46px;width:7px;height:7px;border:1px solid #d6e8df;border-radius:50%}.reticle-top,.reticle-bottom{position:absolute;left:61px;width:2px;height:10px;background:#b8d7d2}.reticle-top{top:0}.reticle-bottom{top:89px}.reticle-left,.reticle-right{position:absolute;top:48px;width:10px;height:2px;background:#b8d7d2}.reticle-left{left:10px}.reticle-right{right:10px}.lock-label{position:absolute;bottom:0;left:0;width:100%;text-align:center;font-size:7px;letter-spacing:2px;color:#a6bec0}.reticle.locking .reticle-circle{border-color:var(--amber);box-shadow:0 0 12px rgba(245,174,87,.3)}.reticle.locked .reticle-circle{border:2px solid #f27864;box-shadow:0 0 16px rgba(242,100,81,.55);animation:lockpulse .7s ease-in-out infinite alternate}.reticle.locked .lock-label{color:#ff816e}.warning-banner{position:absolute;top:17%;left:50%;transform:translateX(-50%);padding:8px 17px;background:rgba(82,20,19,.72);border:1px solid rgba(249,100,76,.6);color:#ff9b80;font-size:10px;letter-spacing:1.8px;opacity:0;transition:opacity .2s}.warning-banner.active{opacity:1;animation:warn .55s infinite alternate}.warning-banner>span:first-child{margin-right:8px}.warning-distance{margin-left:14px;color:#f6ddd1;font-size:8px}.hit-flash{position:absolute;inset:0;pointer-events:none;box-shadow:inset 0 0 100px rgba(249,65,48,0);transition:box-shadow .12s}.hit-flash.active{box-shadow:inset 0 0 130px rgba(249,65,48,.5)}.bottom-hud{position:absolute;left:29px;right:29px;bottom:30px;display:flex;align-items:flex-end;justify-content:space-between;pointer-events:none}.integrity,.boost-indicator{width:174px}.integrity-track,.boost-track{margin-top:7px;width:100%;height:4px;background:rgba(110,140,147,.35)}.integrity-track i,.boost-track i{display:block;height:100%;width:100%;background:#83d1b3;transition:width .2s}.integrity b,.boost-indicator>b{position:absolute;margin-top:5px;margin-left:7px;font-size:8px;color:#b8c9c8}.center-readout{font-size:8px;letter-spacing:1.2px;color:#96aaae}.center-readout i{color:#d9e2dd;font-style:normal;font-weight:600}.center-readout b{color:#d4e4dd}.separator{padding:0 10px;color:#5f777e}.boost-indicator{text-align:right}.boost-track i{margin-left:auto;background:#efad61}.boost-indicator>b{position:relative;display:block;margin:4px 0 0 auto;color:#e4b575}.toast{position:absolute;left:50%;top:68%;transform:translate(-50%,10px);font-size:10px;letter-spacing:2px;color:#e3efdc;text-shadow:0 1px 6px #000;opacity:0;transition:.3s;pointer-events:none}.toast.show{opacity:1;transform:translate(-50%,0)}.screen-footer{position:absolute;left:29px;right:29px;bottom:10px;display:flex;justify-content:space-between;color:#789098;font-size:7px;letter-spacing:1px}.screen-footer b{color:#b4cfca;font-weight:500}.rain-icon{font-size:11px;margin-left:4px;color:#94bfca}.overlay,.result-overlay{position:absolute;inset:0;z-index:5;display:flex;align-items:center;justify-content:center;background:rgba(3,10,15,.49);backdrop-filter:blur(3px)}.briefing-card{position:relative;width:min(490px,calc(100vw - 32px));padding:24px 35px 22px;background:linear-gradient(145deg,rgba(8,22,30,.97),rgba(8,20,27,.91));border:1px solid rgba(157,205,211,.32);box-shadow:0 20px 70px rgba(0,0,0,.4);clip-path:polygon(0 0,96% 0,100% 5%,100% 100%,4% 100%,0 96%);animation:cardin .5s ease-out}.card-kicker{display:flex;justify-content:space-between;font-size:7px;letter-spacing:1px;color:#8ba4aa}.card-kicker span:first-child{color:#e49f63}.card-line{height:1px;background:linear-gradient(90deg,#c9894d,rgba(180,209,211,.2),transparent);margin:12px 0 20px}.eyebrow{font-size:8px;letter-spacing:2.4px;color:#91b8b8}.briefing-card h1,.result-card h2{font:900 78px/.72 'Barlow Condensed',sans-serif;letter-spacing:1.5px;margin:12px 0 12px;color:#e9efea}.briefing-card h1 em,.result-card h2 em{font-style:normal;color:#a8cdca}.subtitle{font-size:12px;letter-spacing:3.6px;color:#e2a35f;font-weight:600}.briefing-copy{max-width:390px;font-size:10px;line-height:1.8;color:#a6b8b9;margin:17px 0}.briefing-copy b{color:#e2e8df}.briefing-data{display:grid;grid-template-columns:repeat(3,1fr);padding:11px 0;border-top:1px solid rgba(145,182,188,.18);border-bottom:1px solid rgba(145,182,188,.18);margin:12px 0 15px}.briefing-data div{display:grid;gap:5px}.briefing-data span,.result-stats span{font-size:6px;letter-spacing:1px;color:#718a92}.briefing-data b{font-size:7px;letter-spacing:.3px;color:#d1dfd9}.primary-button{display:flex;align-items:center;gap:11px;width:100%;height:43px;padding:0 15px;border:1px solid #b78a5a;background:linear-gradient(90deg,rgba(121,81,47,.65),rgba(87,66,43,.4));color:#f3c08a;cursor:pointer;text-align:left;font-size:10px;letter-spacing:1.2px;transition:background .2s,border .2s,transform .2s}.primary-button:hover{background:linear-gradient(90deg,rgba(155,99,53,.8),rgba(112,79,47,.5));border-color:#f0b879;transform:translateY(-1px)}.primary-button span{font-size:13px}.primary-button i{font-style:normal;margin-left:auto;font-size:7px;letter-spacing:1.5px;color:#c0a485}.controls-hint{display:flex;justify-content:space-between;margin-top:13px;color:#8da4a6;font-size:6px;letter-spacing:.4px}.controls-hint b{color:#d4e1d9;font-weight:500;margin-left:3px}.overlay-footer{position:absolute;bottom:24px;left:30px;right:30px;display:flex;justify-content:space-between;color:#728b91;font-size:7px;letter-spacing:1px}.overlay-footer i{font-style:normal;color:#83d1b3}.hidden{display:none!important}.result-card{width:min(410px,calc(100vw - 36px));padding:32px;background:rgba(7,20,28,.96);border:1px solid rgba(152,206,206,.35);box-shadow:0 18px 70px #0008}.result-card h2{font-size:61px;margin:16px 0}.result-card p{color:#a7b9b8;font-size:10px}.result-stats{display:grid;grid-template-columns:repeat(3,1fr);padding:16px 0;margin:20px 0;border-top:1px solid var(--line);border-bottom:1px solid var(--line)}.result-stats div{display:grid;gap:6px}.result-stats b{font:600 24px 'Barlow Condensed';color:#dce9e2}.pause-badge{position:absolute;z-index:4;left:50%;top:45%;transform:translate(-50%,-50%);padding:18px 25px;border:1px solid #abc8c3;background:#06151ddd;font:700 28px 'Barlow Condensed';letter-spacing:3px;color:#e8f1e8}.pause-badge span{display:block;text-align:center;margin-top:5px;font:8px 'IBM Plex Mono';letter-spacing:1.5px;color:#96b1b1}.touch-controls{display:none;position:absolute;left:18px;right:18px;bottom:68px;justify-content:space-between;align-items:flex-end;z-index:3;pointer-events:none}.touch-pad,.touch-actions{pointer-events:auto;display:flex;align-items:center;gap:5px}.touch-pad>div{display:grid;gap:5px}.touch-controls button{width:39px;height:39px;border:1px solid #b3d5d066;background:#071821a8;color:#d7e8e1;border-radius:50%;font-size:13px;touch-action:none}.touch-actions{display:grid;grid-template-columns:repeat(2,52px)}.touch-actions button{width:52px;height:42px;border-radius:6px;font-size:8px;letter-spacing:.5px}.touch-actions .fire-touch{color:#9fe0d0}.touch-actions .missile-touch{color:#f0b870}.touch-actions .boost-touch{grid-column:span 2;width:100%;height:30px}.mobile .touch-controls{display:flex}.mobile .hud-left{top:20%;left:12px;transform:scale(.82);transform-origin:top left}.mobile .hud-right{top:20%;right:12px;transform:scale(.8);transform-origin:top right}.mobile .mission-strip{top:66px;width:94vw}.mobile .mission-label{display:none}.mobile .topbar{padding:0 13px}.mobile .bottom-hud{left:13px;right:13px;bottom:119px}.mobile .integrity,.mobile .boost-indicator{width:105px}.mobile .center-readout{font-size:6px}.mobile .screen-footer{left:13px;right:13px;bottom:10px}.mobile .reticle{top:51%;transform:translate(-50%,-50%) scale(.75)}.mobile .briefing-card{padding:20px 22px}.mobile .briefing-card h1{font-size:62px}.mobile .briefing-copy{font-size:9px}.mobile .overlay-footer{left:14px;right:14px;bottom:22px}.mobile .controls-hint{gap:7px;font-size:5px}.mobile .briefing-data b{font-size:6px}
@keyframes sweep{to{transform:rotate(360deg)}}@keyframes lockpulse{to{opacity:.55}}@keyframes warn{to{filter:brightness(1.6)}}@keyframes cardin{from{opacity:0;transform:translateY(12px)}to{opacity:1;transform:none}}
@media(max-width:700px){.topbar{height:48px;font-size:8px}.top-right{font-size:7px}.brand{gap:7px}.brand-mark{width:23px;height:23px}.hud-left{top:18%!important}.hud-right{top:18%!important}.radar-panel{display:none}.hud-right{width:140px}.weapon-panel{padding:7px}.weapon-row{height:35px}.weapon-name b{font-size:8px}.hud-card{padding:7px 8px}.hud-card strong{font-size:20px!important}.speed-card strong{font-size:23px!important}.threat-card{padding-top:7px;padding-bottom:7px}.hud-caption{font-size:6px}.mission-strip{height:36px}.mission-objective{font-size:7px}.mission-progress{font-size:8px}.bottom-hud{bottom:111px!important}.screen-footer{font-size:6px}.overlay-footer{bottom:9px}.briefing-card{max-height:calc(100dvh - 60px);overflow:auto}.briefing-data{margin:9px 0}.briefing-copy{margin:12px 0}}
@media(max-height:650px) and (min-width:701px){.briefing-card{padding:17px 28px}.briefing-card h1{font-size:62px}.briefing-copy{margin:10px 0}.briefing-data{margin:8px 0}.hud-left,.hud-right{top:20%}.bottom-hud{bottom:20px}.screen-footer{bottom:5px}}

(() => {
  const canvas = document.getElementById('game');
  const ctx = canvas.getContext('2d');
  const $ = (id) => document.getElementById(id);
  const ui = { overlay:$('overlay'), result:$('result-overlay'), pause:$('pause-badge'), objective:$('objective'), progress:$('progress'), kills:$('kills'), time:$('clock'), altitude:$('altitude'), altMeter:$('alt-meter'), speed:$('speed'), speedState:$('speed-state'), threat:$('threat'), health:$('health'), healthBar:$('health-bar'), boostBar:$('boost-bar'), boostText:$('boost-text'), missiles:$('missile-count'), reticle:$('reticle'), lock:$('lock-label'), warning:$('warning'), hit:$('hit-flash'), toast:$('toast') };
  const isMobile = matchMedia('(pointer: coarse)').matches || innerWidth < 700;
  if (isMobile) document.body.classList.add('mobile');
  let W=0,H=0,dpr=1,last=0, gameState='briefing', elapsed=0, kills=0, health=100, missiles=4, boost=100, playerX=0, playerY=0, targetLock=0, audioCtx=null, toastTimer=0;
  const keys = new Set(), enemies=[], bullets=[], rockets=[], particles=[], rain=[];
  let spawnTimer=0, fireTimer=0, missileTimer=0, shake=0, flash=0, stormFlash=0, stormTimer=8, damageCooldown=0, targetId=0;
  const rand=(a,b)=>a+Math.random()*(b-a), clamp=(n,a,b)=>Math.max(a,Math.min(b,n));
  const resize=()=>{dpr=Math.min(devicePixelRatio||1,2); W=canvas.clientWidth;H=canvas.clientHeight;canvas.width=Math.round(W*dpr);canvas.height=Math.round(H*dpr);ctx.setTransform(dpr,0,0,dpr,0,0);};
  addEventListener('resize',resize); resize();
  function seedRain(){rain.length=0;for(let i=0;i<Math.max(90,Math.round(W*H/3900));i++)rain.push({x:Math.random()*W,y:Math.random()*H,len:rand(8,25),speed:rand(550,1100),a:rand(.08,.38)});} seedRain();
  function sound(freq=360,duration=.08,type='square',vol=.025){try{audioCtx ||= new (window.AudioContext||window.webkitAudioContext)();const o=audioCtx.createOscillator(),g=audioCtx.createGain();o.type=type;o.frequency.value=freq;g.gain.setValueAtTime(vol,audioCtx.currentTime);g.gain.exponentialRampToValueAtTime(.001,audioCtx.currentTime+duration);o.connect(g);g.connect(audioCtx.destination);o.start();o.stop(audioCtx.currentTime+duration);}catch(_){}}
  function showToast(text){ui.toast.textContent=text;ui.toast.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>ui.toast.classList.remove('show'),1250);}
  function formatTime(s){const m=Math.floor(s/60),ss=Math.floor(s%60);return `${String(m).padStart(2,'0')}:${String(ss).padStart(2,'0')}`;}
  function startGame(){audioCtx?.resume?.();gameState='playing';elapsed=0;kills=0;health=100;missiles=4;boost=100;playerX=0;playerY=0;targetLock=0;spawnTimer=.45;fireTimer=0;missileTimer=0;damageCooldown=0;enemies.length=0;bullets.length=0;rockets.length=0;particles.length=0;ui.overlay.classList.add('hidden');ui.result.classList.add('hidden');ui.pause.classList.add('hidden');updateHud();showToast('RAVEN 1 — ENGAGE');sound(250,.14,'sawtooth');}
  function endGame(won){gameState='result';ui.result.classList.remove('hidden');$('result-kicker').textContent=won?'MISSION COMPLETE':'AIRCRAFT LOST';$('result-title').innerHTML=won?'CORRIDOR<br><em>SECURED</em>':'MISSION<br><em>FAILED</em>';$('result-copy').textContent=won?'All hostile aircraft neutralized. The Cape corridor is secure.':'Airframe critical. Raven 1, mission aborted.';$('final-kills').textContent=String(kills).padStart(2,'0');$('final-health').textContent=`${Math.max(0,Math.round(health))}%`;$('final-time').textContent=formatTime(elapsed);sound(won?590:120,.4,won?'triangle':'sawtooth',.05);}
  $('start-button').addEventListener('click',startGame);$('restart-button').addEventListener('click',startGame);
  function setKey(code,on){if(on)keys.add(code);else keys.delete(code);}
  addEventListener('keydown',e=>{if(['ArrowUp','ArrowDown','ArrowLeft','ArrowRight','Space'].includes(e.code))e.preventDefault();if(e.repeat)return;if(e.code==='KeyP'&&gameState==='playing'){gameState='paused';ui.pause.classList.remove('hidden');return;}if(e.code==='KeyP'&&gameState==='paused'){gameState='playing';ui.pause.classList.add('hidden');last=performance.now();return;}setKey(e.code,true);if(gameState==='briefing'&&(e.code==='Enter'||e.code==='Space'))startGame();});
  addEventListener('keyup',e=>setKey(e.code,false));
  document.querySelectorAll('.touch-controls button').forEach(button=>{const code=button.dataset.key;button.addEventListener('pointerdown',e=>{e.preventDefault();button.setPointerCapture(e.pointerId);setKey(code,true);});for(const ev of ['pointerup','pointercancel','lostpointercapture'])button.addEventListener(ev,()=>setKey(code,false));});
  function spawnEnemy(){if(enemies.length>6)return;const side=Math.random()<.5?-1:1;const x=rand(-.8,.8);enemies.push({id:++targetId,x,y:rand(-.08,.12),speed:rand(.045,.075),side,phase:rand(0,6),hp:Math.random()<.21?2:1,fire:rand(2,5),type:Math.random()<.3?'heavy':'interceptor',alive:true,scored:false});}
  function shoot(){if(fireTimer>0)return;fireTimer=.115;bullets.push({x:playerX,y:.75,vy:-1.35,life:.8});sound(rand(120,180),.045,'sawtooth',.018);}
  function launchMissile(){if(missileTimer>0||missiles<=0)return;const t=nearestEnemy();if(!t){showToast('NO HOSTILE TRACK');sound(220,.08,'triangle',.015);return;}missileTimer=.7;missiles--;ui.missiles.textContent=String(missiles).padStart(2,'0');rockets.push({x:playerX,y:.73,target:t,life:5});sound(450,.16,'triangle',.03);showToast('PHOENIX AWAY');}
  function nearestEnemy(){let best=null,dist=Infinity;for(const e of enemies){if(!e.alive)continue;const d=Math.hypot((e.x-playerX)*W,(e.y-.48)*H);if(d<dist){best=e;dist=d;}}return best;}
  function hitEnemy(e){if(!e.alive)return;e.hp--;if(e.hp<=0){e.alive=false;kills++;ui.kills.textContent=String(kills).padStart(2,'0');ui.progress.style.width=`${kills/6*100}%`;for(let i=0;i<26;i++)particles.push({x:e.x,y:e.y,vx:rand(-.35,.35),vy:rand(-.45,.3),life:rand(.35,.9),max:.9,size:rand(1,5),color:Math.random()<.45?'#ffb96a':'#d7e5d6'});shake=Math.max(shake,7);sound(80,.2,'sawtooth',.04);showToast(['SPLASH ONE','HOSTILE DOWN','TARGET DESTROYED'][Math.floor(Math.random()*3)]);if(kills>=6){setTimeout(()=>{if(gameState==='playing')endGame(true);},900);}}else{sound(170,.06,'square');}}
  function damage(){if(damageCooldown>0)return;damageCooldown=1.1;health-=rand(9,15);health=Math.max(0,health);shake=12;flash=.25;ui.hit.classList.add('active');setTimeout(()=>ui.hit.classList.remove('active'),170);sound(65,.18,'sawtooth',.04);showToast('AIRFRAME HIT');if(health<=0)setTimeout(()=>{if(gameState==='playing')endGame(false);},500);}
  function updateHud(){ui.health.textContent=`${Math.round(health)}%`;ui.healthBar.style.width=`${health}%`;ui.healthBar.style.background=health<35?'#f26659':'#83d1b3';ui.boostBar.style.width=`${boost}%`;ui.boostText.textContent=boost>=98?'READY':boost>10?'CHARGING':'DEPLETED';ui.speed.textContent=String(Math.round(1640+(boost>0&&keys.has('ShiftLeft')?600:200)+Math.abs(playerX)*90)).replace(/\B(?=(\d{3})+(?!\d))/g,',');ui.speedState.innerHTML=`MACH ${boost>0&&keys.has('ShiftLeft')?'3.5':'2.8'} <span>●</span>`;ui.altitude.textContent=String(Math.round(18400-playerY*3000)).replace(/\B(?=(\d{3})+(?!\d))/g,',');ui.altMeter.style.width=`${clamp(67-playerY*20,20,90)}%`;ui.time.textContent=formatTime(elapsed);const threat=enemies.length>3?'HIGH':enemies.length>1?'MED':'LOW';ui.threat.textContent=threat;ui.threat.style.color=threat==='HIGH'?'#f2745f':threat==='MED'?'#efb35f':'#8ad6b7';document.querySelector('.threat-dot').style.background=threat==='HIGH'?'#f2745f':threat==='MED'?'#efb35f':'#79d4a9';}
  function update(dt){if(gameState!=='playing')return;elapsed+=dt;fireTimer=Math.max(0,fireTimer-dt);missileTimer=Math.max(0,missileTimer-dt);damageCooldown=Math.max(0,damageCooldown-dt);spawnTimer-=dt;stormTimer-=dt;shake=Math.max(0,shake-dt*19);flash=Math.max(0,flash-dt);
    if(stormTimer<=0){stormFlash=1;stormTimer=rand(7,15);sound(rand(35,55),.45,'sawtooth',.025);}
    const left=keys.has('ArrowLeft')||keys.has('KeyA'),right=keys.has('ArrowRight')||keys.has('KeyD'),up=keys.has('ArrowUp')||keys.has('KeyW'),down=keys.has('ArrowDown')||keys.has('KeyS');const boosting=(keys.has('ShiftLeft')||keys.has('ShiftRight'))&&boost>0;
    const accel=boosting?1.45:1;playerX=clamp(playerX+((right?1:0)-(left?1:0))*dt*.62*accel,-.82,.82);playerY=clamp(playerY+((down?1:0)-(up?1:0))*dt*.55*accel,-.7,.7);boost=clamp(boost+(boosting?-dt*29:dt*13),0,100);if(keys.has('Space'))shoot();if(keys.has('KeyX'))launchMissile();
    if(spawnTimer<=0&&kills<6){spawnEnemy();spawnTimer=rand(1.45,2.4)*Math.max(.66,1-kills*.045);}
    for(const e of enemies){if(!e.alive)continue;e.phase+=dt*1.1;e.y+=e.speed*dt*(boosting?1.18:1);e.x+=Math.sin(e.phase)*dt*.095;e.x=clamp(e.x,-.92,.92);e.fire-=dt;
      if(e.y>.83&&!e.scored){e.scored=true;damage();e.alive=false;}
      if(e.fire<=0&&e.y>.12&&e.y<.72){e.fire=rand(3.2,5.3);bullets.push({x:e.x,y:e.y,vy:.34,enemy:true,life:2});}
    }
    for(let i=bullets.length-1;i>=0;i--){const b=bullets[i];b.y+=b.vy*dt;b.life-=dt;if(b.enemy){if(Math.hypot((b.x-playerX)*W,(b.y-.73)*H)<22){damage();bullets.splice(i,1);continue;}}else{for(const e of enemies){if(e.alive&&Math.hypot((e.x-b.x)*W,(e.y-b.y)*H)<Math.max(18,30*e.y)){hitEnemy(e);bullets.splice(i,1);break;}}}if(b.life<=0||b.y<-.1||b.y>1.1)bullets.splice(i,1);}
    for(let i=rockets.length-1;i>=0;i--){const r=rockets[i];r.life-=dt;if(!r.target.alive){const t=nearestEnemy();if(t)r.target=t;}if(r.target.alive){const dx=r.target.x-r.x,dy=r.target.y-r.y,d=Math.hypot(dx,dy)||1;r.x+=dx/d*dt*.8;r.y+=dy/d*dt*.8;if(d<.09){hitEnemy(r.target);rockets.splice(i,1);continue;}}if(r.life<=0)rockets.splice(i,1);}
    for(let i=particles.length-1;i>=0;i--){const p=particles[i];p.x+=p.vx*dt;p.y+=p.vy*dt;p.vy+=dt*.15;p.life-=dt;if(p.life<=0)particles.splice(i,1);}
    const target=nearestEnemy();if(target){const distance=Math.hypot((target.x-playerX)*W,(target.y-.4)*H);targetLock=clamp(targetLock+(distance<105?dt*.85:-dt*.65),0,1);}else targetLock=Math.max(0,targetLock-dt);ui.reticle.classList.toggle('locking',targetLock>0.1&&targetLock<.95);ui.reticle.classList.toggle('locked',targetLock>=.95);ui.lock.textContent=targetLock>=.95?'LOCKED':targetLock>0.1?'ACQUIRING':'NO LOCK';ui.warning.classList.toggle('active',enemies.some(e=>e.alive&&e.y>.45&&e.y<.72));updateHud();
  }
  function drawBackground(dt){const sky=ctx.createLinearGradient(0,0,0,H);sky.addColorStop(0,'#1c3038');sky.addColorStop(.28,'#40535a');sky.addColorStop(.42,'#263941');sky.addColorStop(1,'#0b171d');ctx.fillStyle=sky;ctx.fillRect(0,0,W,H);
    // Storm bank and distant Cape silhouette
    const horizon=H*.37;ctx.fillStyle='rgba(6,17,23,.68)';ctx.beginPath();ctx.moveTo(0,horizon+22);for(let x=0;x<=W+40;x+=35){const v=Math.sin(x*.012)*13+Math.sin(x*.031)*8;ctx.lineTo(x,horizon+v+rand(-2,2));}ctx.lineTo(W,horizon+65);ctx.lineTo(0,horizon+65);ctx.fill();
    ctx.fillStyle='rgba(87,112,117,.16)';for(let i=0;i<8;i++){const x=((i*W/6+elapsed*5)%(W+300))-100,y=H*(.07+(i%4)*.06);ctx.beginPath();ctx.ellipse(x,y,rand(70,170),rand(15,35),0,0,Math.PI*2);ctx.fill();}
    // Ocean facets
    const sea=ctx.createLinearGradient(0,horizon,0,H);sea.addColorStop(0,'#263b41');sea.addColorStop(.45,'#14282f');sea.addColorStop(1,'#08151c');ctx.fillStyle=sea;ctx.fillRect(0,horizon,W,H-horizon);
    for(let i=0;i<54;i++){const y=horizon+((i*37+elapsed*(30+i*3))%(H-horizon));const perspective=(y-horizon)/(H-horizon);const width=rand(8,100)*perspective+8;const x=((i*97+Math.sin(i*12)*60+elapsed*(i%2?12:-9))%(W+130))-60;ctx.fillStyle=`rgba(${100+Math.floor(perspective*50)},${145+Math.floor(perspective*35)},${150+Math.floor(perspective*25)},${.025+perspective*.12})`;ctx.fillRect(x,y,width*perspective+10,1+perspective*2);}
    // Rain sheets
    ctx.save();ctx.lineWidth=1;for(const r of rain){r.y+=r.speed*dt;r.x-=r.speed*.12*dt;if(r.y>H+30){r.y=-30;r.x=Math.random()*W;}if(r.x<-20)r.x=W+10;ctx.strokeStyle=`rgba(192,220,224,${r.a})`;ctx.beginPath();ctx.moveTo(r.x,r.y);ctx.lineTo(r.x-5,r.y+r.len);ctx.stroke();}ctx.restore();
    if(stormFlash>0){stormFlash=Math.max(0,stormFlash-dt*2.7);ctx.fillStyle=`rgba(191,224,227,${stormFlash*.2})`;ctx.fillRect(0,0,W,H);}
  }
  function drawEnemy(e){if(!e.alive)return;const x=W*(.5+e.x*.42),y=H*(.38+e.y*.58),scale=.22+clamp(e.y,0,.8)*.9;ctx.save();ctx.translate(x,y);ctx.scale(scale,scale);ctx.fillStyle=e.type==='heavy'?'#26363a':'#18282f';ctx.strokeStyle='rgba(183,207,203,.48)';ctx.lineWidth=1.3;ctx.beginPath();ctx.moveTo(0,-29);ctx.lineTo(5,-9);ctx.lineTo(26,3);ctx.lineTo(27,8);ctx.lineTo(7,3);ctx.lineTo(4,17);ctx.lineTo(12,23);ctx.lineTo(12,26);ctx.lineTo(0,22);ctx.lineTo(-12,26);ctx.lineTo(-12,23);ctx.lineTo(-4,17);ctx.lineTo(-7,3);ctx.lineTo(-27,8);ctx.lineTo(-26,3);ctx.lineTo(-5,-9);ctx.closePath();ctx.fill();ctx.stroke();ctx.fillStyle=e.hp>1?'#e98b5f':'#e06454';ctx.fillRect(-3,-8,6,2);ctx.restore();}
  function drawPlayer(){const x=W*(.5+playerX*.33),y=H*(.75+playerY*.11);const roll=(keys.has('ArrowRight')||keys.has('KeyD')?1:0)-(keys.has('ArrowLeft')||keys.has('KeyA')?1:0);ctx.save();ctx.translate(x,y);ctx.rotate(roll*.055);const scale=Math.min(W/1000,1.3);ctx.scale(scale,scale);
    // exhaust glow
    const glow=ctx.createRadialGradient(0,30,1,0,30,50);glow.addColorStop(0,keys.has('ShiftLeft')||keys.has('ShiftRight')?'rgba(255,172,78,.55)':'rgba(143,206,206,.23)');glow.addColorStop(1,'transparent');ctx.fillStyle=glow;ctx.fillRect(-55,-5,110,95);
    ctx.fillStyle='#111f25';ctx.strokeStyle='rgba(171,201,200,.62)';ctx.lineWidth=1.1;ctx.beginPath();ctx.moveTo(0,-53);ctx.lineTo(7,-26);ctx.lineTo(65,7);ctx.lineTo(69,16);ctx.lineTo(13,-1);ctx.lineTo(10,26);ctx.lineTo(25,41);ctx.lineTo(24,46);ctx.lineTo(3,39);ctx.lineTo(0,46);ctx.lineTo(-3,39);ctx.lineTo(-24,46);ctx.lineTo(-25,41);ctx.lineTo(-10,26);ctx.lineTo(-13,-1);ctx.lineTo(-69,16);ctx.lineTo(-65,7);ctx.lineTo(-7,-26);ctx.closePath();ctx.fill();ctx.stroke();ctx.fillStyle='#728a8d';ctx.beginPath();ctx.moveTo(0,-49);ctx.lineTo(3,-26);ctx.lineTo(0,-13);ctx.lineTo(-3,-26);ctx.closePath();ctx.fill();ctx.fillStyle='#ffae65';ctx.globalAlpha=.7;ctx.fillRect(-20,41,6,3);ctx.fillRect(14,41,6,3);
    if(keys.has('Space')){ctx.strokeStyle='rgba(255,211,133,.92)';ctx.lineWidth=2;ctx.beginPath();ctx.moveTo(-13,-26);ctx.lineTo(-13,-68);ctx.moveTo(13,-26);ctx.lineTo(13,-68);ctx.stroke();ctx.fillStyle='rgba(255,230,174,.9)';ctx.fillRect(-15,-70,4,5);ctx.fillRect(11,-70,4,5);}ctx.restore();}
  function render(dt){ctx.save();if(shake>0)ctx.translate(rand(-shake,shake),rand(-shake,shake));drawBackground(dt);
    for(const e of enemies)drawEnemy(e);
    for(const b of bullets){const x=W*(.5+b.x*.42),y=H*(.38+b.y*.58);ctx.strokeStyle=b.enemy?'rgba(255,91,75,.88)':'rgba(255,223,148,.94)';ctx.lineWidth=b.enemy?2:3;ctx.beginPath();ctx.moveTo(x,y);ctx.lineTo(x,y+(b.enemy?12:-19));ctx.stroke();}
    for(const r of rockets){const x=W*(.5+r.x*.42),y=H*(.38+r.y*.58);ctx.fillStyle='#ffc06b';ctx.shadowColor='#ff9550';ctx.shadowBlur=14;ctx.beginPath();ctx.arc(x,y,3,0,Math.PI*2);ctx.fill();ctx.shadowBlur=0;ctx.strokeStyle='rgba(250,156,79,.65)';ctx.beginPath();ctx.moveTo(x,y+5);ctx.lineTo(x-3,y+22);ctx.stroke();}
    for(const p of particles){const x=W*(.5+p.x*.42),y=H*(.38+p.y*.58);ctx.globalAlpha=clamp(p.life/p.max,0,1);ctx.fillStyle=p.color;ctx.beginPath();ctx.arc(x,y,p.size,0,Math.PI*2);ctx.fill();}ctx.globalAlpha=1;
    drawPlayer();ctx.restore();}
  function frame(now){const dt=Math.min(.04,(now-last)/1000||0);last=now;if(gameState==='playing')update(dt);render(dt);requestAnimationFrame(frame);}requestAnimationFrame(frame);
})();

